// Abstract products: one interface per role.
interface Button { void render(); }
interface Checkbox { void toggle(); }

// Abstract factory: one creation method per role.
interface GuiFactory {
    Button createButton();
    Checkbox createCheckbox();
}

// One concrete family. Products here share theme tokens,
// focus behaviour, and accessibility contracts.
final class LightButton implements Button {
    public void render() { System.out.println("light button"); }
}
final class LightCheckbox implements Checkbox {
    public void toggle() { System.out.println("light toggle"); }
}
final class LightFactory implements GuiFactory {
    public Button createButton() { return new LightButton(); }
    public Checkbox createCheckbox() { return new LightCheckbox(); }
}

final class DarkButton implements Button {
    public void render() { System.out.println("dark button"); }
}
final class DarkCheckbox implements Checkbox {
    public void toggle() { System.out.println("dark toggle"); }
}
final class DarkFactory implements GuiFactory {
    public Button createButton() { return new DarkButton(); }
    public Checkbox createCheckbox() { return new DarkCheckbox(); }
}

// Client depends only on abstractions. No instanceof, no theme flag.
final class SettingsScreen {
    private final GuiFactory factory;
    SettingsScreen(GuiFactory factory) { this.factory = factory; }
    void build() {
        Button b = factory.createButton();
        Checkbox c = factory.createCheckbox();
        b.render();
        c.toggle();
    }
}

final class FactoryProvider {
    private final java.util.Map<String, GuiFactory> byName = java.util.Map.of(
        "light", new LightFactory(),
        "dark", new DarkFactory()
    );
    GuiFactory resolve(String theme) {
        GuiFactory f = byName.get(theme.toLowerCase());
        if (f == null) throw new IllegalArgumentException("unknown theme: " + theme);
        return f;
    }
}
